# Homebrew cask for Diorama 1.9.1 (generated by scripts/release-notes.sh)
cask "diorama" do
  version "1.9.1"
  sha256 "b7bc5267b81448129e692c24a2f2f8b35b3c6f2bf46d471d9f4f70a2890b41f3"

  url "https://github.com/ridvanaltun/diorama/releases/download/v#{version}/Diorama-#{version}.zip"
  name "Diorama"
  desc "Steer and study the tool results Claude Code receives"
  homepage "https://github.com/ridvanaltun/diorama"

  depends_on macos: :sequoia

  app "Diorama.app"
  binary "#{appdir}/Diorama.app/Contents/Helpers/diorama"

  uninstall launchctl: "io.github.diorama.daemon",
            quit:      "io.github.diorama.Diorama"

  # Takes Diorama's hook out of every connected project's Claude Code settings before the app goes
  # (not on upgrade: Homebrew runs zap only for `brew uninstall --zap`). Hooks left by a plain
  # uninstall do nothing once the CLI is gone.
  zap script: {
        executable:   "/bin/sh",
        args:         ["-c", '[ -x "$1" ] && "$1" hook uninstall --all; exit 0', "sh",
                       "#{appdir}/Diorama.app/Contents/Helpers/diorama"],
        must_succeed: false,
      },
      trash:  "~/Library/Application Support/Diorama"

  caveats <<~EOS
    Diorama isn't notarized by Apple, so macOS blocks its first launch.
    Open System Settings > Privacy & Security and click "Open Anyway" for Diorama
    (once), or run:
      xattr -dr com.apple.quarantine "#{appdir}/Diorama.app"
  EOS
end
